#!/usr/bin/env python3
"""
Round 134b (culprits), 2 October 2026. Needs round 133b.

Glowing orbs, all farm animals, slaughterhouse sizes, one slaughterhouse row.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 134b (2 October)\n\nNeeds round 133b. Tiles patch round134b_tiles.py beside it. No app.js?v= bump.\n\n- Points: the glowing orbs again (asked 2 October): cores soft-edged\n  (circle-blur 0.6, round 119b had 0.12) and the dots soft (0.8, was 0.15);\n  the light rim close in (125b) stays.\n- How many farm animals are kept: an All choice, first (every animal counted\n  as one head or bird, the six FAO GLW4 grids added; tiles glw_relief.py\n  writes glw_all). Until it is built the row opens on cattle as before.\n- Registered animal-use facilities: the colour menu says each value in words\n  (US FSIS sizes: large 500+ employees, small 10-499, very small under 10 or\n  under $2.5 million in sales; "N / A" and "1.0" as the register gives them);\n  a Size filter under the row (keys), with "no size given" as its own choice\n  (missingLabel, __none__ in keyFilterExpr). Only the US register gives a\n  size; Trase\'s capacities are in each box but in mixed units, so no filter.\n- trase_meat_brazil out (PANEL_REMOVED): the abattoir atlas reads Trase\'s\n  whole facilities file (15,119 rows) into abattoir_facilities, one point per\n  site with SIF and the other registers, every Trase field in the box.\n- GDACS alert levels in words and EONET were done in round 123b; EONET\'s file\n  is built on tiles main.\n\n']


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round134b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 133b" not in h.read_text(encoding="utf-8"):
        sys.exit("round134b: round 133b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round134b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", "map/index.html", check=False)
            sys.exit("round134b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round134b: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


DIFF = ''

if __name__ == "__main__":
    main()
